1	import { Debounce } from "../utils/Debounce.js";
2	import type { Engine } from "../core/Engine.js";
3	import type { ISetup, ResizeSetupOptions } from "../types/runtime.types.js";
4	import { ResponsiveRuntime } from "../runtime/ResponsiveRuntime.js";
5	
6	export { type ResizeSetupOptions } from "../types/runtime.types.js";
7	
8	export class ResizeSetup
9	  implements ISetup<[Engine, ResizeSetupOptions | number | undefined], void>
10	{
11	  private _engine: Engine | null = null;
12	  private _scrollDriver: { refresh?: () => void } | null = null;
13	  private _debounce: Debounce | null = null;
14	  private _boundHandler: (() => void) | null = null;
15	  private _disposed = false;
16	
17	  init(
18	    engine: Engine,
19	    options: ResizeSetupOptions | number | undefined = 250,
20	  ): void {
21	    this.startListening(engine, options);
22	  }
23	
24	  startListening(
25	    engine: Engine,
26	    options: ResizeSetupOptions | number = 250,
27	  ): void {
28	    if (this._disposed || this._boundHandler) return;
29	    const opts: ResizeSetupOptions =
30	      typeof options === "number" ? { debounceMs: options } : options;
31	    const delayMs = opts.debounceMs ?? 250;
32	    this._engine = engine;
33	    this._scrollDriver = opts.scrollDriver ?? null;
34	    this._debounce = new Debounce(delayMs);
35	    this._boundHandler = (): void => {
36	      this._debounce?.runDebounce(() => {
37	        const runtime = ResponsiveRuntime.getDefault();
38	        runtime.init();
39	        const snapshot = runtime.updateFromWindow();
40	        this._engine?.applyResponsiveSnapshot(snapshot);
41	        this._scrollDriver?.refresh?.();
42	      });
43	    };
44	    const runtime = ResponsiveRuntime.getDefault();
45	    runtime.init();
46	    this._engine.applyResponsiveSnapshot(runtime.getSnapshot());
47	    window.addEventListener("resize", this._boundHandler);
48	  }
49	
50	  register(engine: Engine, options: ResizeSetupOptions | number = 250): void {
51	    this.startListening(engine, options);
52	  }
53	
54	  dispose(): void {
55	    this.stopListening();
56	  }
57	
58	  stopListening(): void {
59	    if (this._disposed) return;
60	    this._disposed = true;
61	    if (this._boundHandler) {
62	      window.removeEventListener("resize", this._boundHandler);
63	      this._boundHandler = null;
64	    }
65	    this._debounce?.dispose();
66	    this._debounce = null;
67	    this._engine = null;
68	    this._scrollDriver = null;
69	  }
70	}
