17	export class Device {
18	  private _viewportWidth = 0;
19	  private _viewportHeight = 0;
20	  private _deviceType: DeviceType = "unknown";
21	
22	  updateFromWindow(): void {
23	    if (typeof window === "undefined") return;
24	    this._viewportWidth = window.innerWidth ?? 0;
25	    this._viewportHeight = window.innerHeight ?? 0;
26	    this._deviceType = detectDeviceType();
27	  }
28	
29	  get viewportWidth(): number {
30	    return this._viewportWidth;
31	  }
32	
33	  get viewportHeight(): number {
34	    return this._viewportHeight;
35	  }
36	
37	  get deviceType(): DeviceType {
38	    return this._deviceType;
39	  }
40	
41	  get isMobile(): boolean {
42	    return this._deviceType === "ios" || this._deviceType === "android";
43	  }
44	
45	  private static _default: Device | null = null;
46	
47	  static getDefault(): Device {
48	    if (!Device._default) {
49	      Device._default = new Device();
50	      if (typeof window !== "undefined") Device._default.updateFromWindow();
51	    }
52	    return Device._default;
53	  }
54	}
