1	import type { PinnedRevealConfig } from "../types/component.types.js";
2	import type { WindowWithGsap } from "../types/gsap.types.js";
3	import type { PinnedRevealEntry } from "../types/runtime.types.js";
4	
5	export class PinnedRevealRuntime {
6	  private readonly _entries = new Set<PinnedRevealEntry>();
7	
8	  init(configs: readonly PinnedRevealConfig[]): void {
9	    this.dispose();
10	    if (typeof document === "undefined") return;
11	    if (configs.length === 0) return;
12	
13	    const win = window as WindowWithGsap;
14	    const gsap = win.gsap;
15	    const ScrollTrigger = win.ScrollTrigger;
16	    if (!gsap || !ScrollTrigger) return;
17	
18	    configs.forEach((config) => {
19	      const section = document.querySelector<HTMLElement>(
20	        config.sectionSelector,
21	      );
22	      const target = document.querySelector<HTMLElement>(config.targetSelector);
23	      if (!section || !target) return;
24	
25	      gsap.killTweensOf?.(target);
26	      const timeline = gsap.timeline({ paused: true });
27	      gsap.set(target, {
28	        autoAlpha: config.animation.fromAutoAlpha,
29	        y: config.animation.fromY,
30	      });
31	
32	      timeline.fromTo(
33	        target,
34	        {
35	          autoAlpha: config.animation.fromAutoAlpha,
36	          y: config.animation.fromY,
37	        },
38	        {
39	          autoAlpha: 1,
40	          y: 0,
41	          duration: config.animation.duration,
42	          ease: config.animation.ease,
43	          immediateRender: false,
44	        },
45	      );
46	
47	      if (config.exitAnimation) {
48	        timeline.to(target, {
49	          autoAlpha: config.exitAnimation.toAutoAlpha,
50	          y: config.exitAnimation.toY,
51	          duration: config.exitAnimation.duration,
52	          ease: config.exitAnimation.ease,
53	          immediateRender: false,
54	        });
55	      }
56	
57	      const trigger = ScrollTrigger.create({
58	        trigger: section,
59	        start: config.start,
60	        end: this._resolveEnd(config.end, section),
61	        scrub: config.scrub,
62	        pin: target,
63	        pinSpacing: config.pinSpacing,
64	        animation: timeline,
65	        invalidateOnRefresh: true,
66	        immediateRender: false,
67	      });
68	
69	      this._entries.add({ target, timeline, trigger });
70	    });
71	  }
72	
73	  dispose(): void {
74	    if (this._entries.size === 0) return;
75	
76	    const win = window as WindowWithGsap;
77	    const gsap = win.gsap;
78	
79	    this._entries.forEach(({ target, timeline, trigger }) => {
80	      trigger.kill();
81	      timeline.kill();
82	      gsap?.killTweensOf?.(target);
83	      gsap?.set(target, { clearProps: "opacity,visibility,transform" });
84	    });
85	    this._entries.clear();
86	  }
87	
88	  private _resolveEnd(
89	    end: PinnedRevealConfig["end"],
90	    section: HTMLElement,
91	  ): string | (() => string) {
92	    if (end !== "viewport-auto") return end;
93	    return () => `+=${Math.max(section.offsetHeight - window.innerHeight, 0)}`;
94	  }
95	}
